INSERT INTO public.business_settings(business_name,timezone) SELECT 'Your Business','UTC' WHERE NOT EXISTS(SELECT 1 FROM public.business_settings);
INSERT INTO public.subscriptions(plan,start_date,end_date,is_active) SELECT 'monthly',current_date,current_date+30,true WHERE NOT EXISTS(SELECT 1 FROM public.subscriptions);
INSERT INTO public.business_hours(day_of_week,day_name,is_closed,is_24h) SELECT n,(ARRAY['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'])[n+1],true,false FROM generate_series(0,6) n ON CONFLICT DO NOTHING;
